// Builds the app the way `wrangler deploy` would, and writes it for the installer to serve:
//   installer/bundle/manifest.json       what Cloudflare needs (modules, bindings, storage migrations, schedule)
//   installer/bundle/files/<module>.txt  each module's code
//   installer/bundle/index.ts            imports them all (generated)
// Usage: node scripts/build-bundle.mjs
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, readdirSync, rmSync, mkdirSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const out = join(root, "installer", "bundle");
const tmp = mkdtempSync(join(tmpdir(), "daybook-bundle-"));

/** JSON with // and /* comments (wrangler.jsonc). Leaves comment-like text inside strings alone. */
function parseJsonc(text) {
  let out = "", i = 0, inString = false;
  while (i < text.length) {
    const c = text[i], n = text[i + 1];
    if (inString) { out += c; if (c === "\\") { out += n; i += 2; continue; } if (c === '"') inString = false; i++; continue; }
    if (c === '"') { inString = true; out += c; i++; continue; }
    if (c === "/" && n === "/") { while (i < text.length && text[i] !== "\n") i++; continue; }
    if (c === "/" && n === "*") { i = text.indexOf("*/", i + 2) + 2; continue; }
    out += c; i++;
  }
  return JSON.parse(out.replace(/,(\s*[}\]])/g, "$1"));
}

const typeFor = name => name.endsWith(".js") || name.endsWith(".mjs") ? "application/javascript+module"
  : /\.(html|txt|md|css|svg)$/.test(name) ? "text/plain" : null;

try {
  execFileSync("npx", ["wrangler", "deploy", "--dry-run", "--outdir", tmp], { cwd: root, stdio: ["ignore", "ignore", "inherit"] });
  const config = parseJsonc(readFileSync(join(root, "wrangler.jsonc"), "utf8"));
  const version = /export const VERSION = "([\d.]+)"/.exec(readFileSync(join(root, "src", "version.ts"), "utf8"))?.[1];
  if (!version) throw new Error("No VERSION in src/version.ts");
  const note = /export const VERSION_NOTE = "((?:[^"\\]|\\.)*)"/.exec(readFileSync(join(root, "src", "version.ts"), "utf8"))?.[1]?.replace(/\\"/g, '"') ?? "";
  const names = readdirSync(tmp).filter(f => !f.endsWith(".map") && f !== "README.md");
  const main = "index.js";
  if (!names.includes(main)) throw new Error("wrangler didn't produce index.js");
  const modules = names.sort((a, b) => (a === main ? -1 : b === main ? 1 : a.localeCompare(b))).map(name => {
    const type = typeFor(name);
    if (!type) throw new Error("The installer can't carry " + name + " yet (only text modules)");
    return { name, type };
  });
  const manifest = {
    version, note, main_module: main, modules,
    compatibility_date: config.compatibility_date, compatibility_flags: config.compatibility_flags ?? [],
    kv: (config.kv_namespaces ?? []).map(k => k.binding),
    durable_objects: (config.durable_objects?.bindings ?? []).map(d => ({ name: d.name, class_name: d.class_name })),
    migrations: config.migrations ?? [],
    crons: config.triggers?.crons ?? []
  };
  rmSync(out, { recursive: true, force: true });
  mkdirSync(join(out, "files"), { recursive: true });
  writeFileSync(join(out, "manifest.json"), JSON.stringify(manifest, null, 2) + "\n");
  const imports = [], entries = [];
  modules.forEach((m, i) => {
    writeFileSync(join(out, "files", m.name + ".txt"), readFileSync(join(tmp, m.name)));
    imports.push(`import m${i} from "./files/${m.name}.txt";`);
    entries.push(`  [${JSON.stringify(m.name)}, m${i}]`);
  });
  writeFileSync(join(out, "index.ts"), `// Generated by scripts/build-bundle.mjs. Don't edit.\n${imports.join("\n")}\nimport manifest from "./manifest.json";\n` +
    `export { manifest };\nexport const files = new Map<string, string>([\n${entries.join(",\n")}\n]);\n`);
  const kb = Math.round(modules.reduce((n, m) => n + readFileSync(join(tmp, m.name)).length, 0) / 1024);
  console.log(`Bundle ${version}: ${modules.map(m => m.name).join(", ")} (${kb} KB) → installer/bundle`);
} finally {
  rmSync(tmp, { recursive: true, force: true });
}
